// AVR/ESP32 flash-storage helpers are provided by Arduino cores, but the
// desktop Jakeboy simulator does not define them. Keep the bitmap in PROGMEM
// on hardware while treating it as ordinary const data in the simulator.
#ifndef PROGMEM
#define PROGMEM
#endif
#ifndef pgm_read_byte
#define pgm_read_byte(addr) (*(const uint8_t *)(addr))
#endif
#ifndef pgm_read_word
#define pgm_read_word(addr) (*(const uint16_t *)(addr))
#endif

