// ============================================================
// Enums
// ============================================================
enum SwitchState {
  SWITCH_UP,
  SWITCH_CENTER,
  SWITCH_DOWN,
  SWITCH_ERROR
};

enum GameState {
  GAME_BOOT,
  GAME_READY,
  GAME_PLAYING,
  GAME_TARGET_HIT,
  GAME_WRONG_HOLE,
  GAME_COMPLETE,
  GAME_OVER
};

// ============================================================
// Structs
// ============================================================
struct DebouncedSwitch {
  SwitchState rawState;
  SwitchState stableState;
  SwitchState previousRawState;
  uint32_t rawChangedAt;
  uint32_t errorStartedAt;
  bool errorActive;
};

struct Hole {
  float x;
  float y;
  float radius;
  int targetNumber; // 0 = trap, 1..10 = numbered target
};

struct RectI {
  int16_t x;
  int16_t y;
  int16_t w;
  int16_t h;
  bool valid;
};

struct VisualState {
  float leftBarY;
  float rightBarY;
  float ballX;
  float ballY;
  float ballRadius;
  bool ballVisible;
};

